def countPrefixSuffixPairs(words):
    count = 0
    n = len(words)
    for i in range(n):
        for j in range(i + 1, n):
            len_i = len(words[i])
            len_j = len(words[j])
            # words[i] must not be longer than words[j]
            if len_i > len_j:
                continue
            # Check prefix
            if words[j][:len_i] != words[i]:
                continue
            # Check suffix
            if words[j][-len_i:] != words[i]:
                continue
            count += 1
    return count
